-- 021: additive columns only; old snapshots, answers and grades remain untouched.
-- Atomic table ALTERs allow crash recovery through the final completion probe.
-- @step question_content
-- @replaces-check 015_demo_slimming/remove_question_rubric
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question') = 20 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND ((COLUMN_NAME IN ('regulation_id', 'version_id', 'category_id', 'concept_id', 'current_version_id') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'difficulty' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('type', 'source') AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO') OR (COLUMN_NAME = 'score' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'NO' AND COLUMN_COMMENT = '题库建议分值；考试实际分值另存'))) = 9 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND ((INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'status' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'type' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_category_pool' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'difficulty' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_concept' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'concept_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_current_version' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'current_version_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 6 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_category_pool') = 4 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_concept') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question' AND INDEX_NAME = 'idx_question_current_version') = 1 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='question' AND ((COLUMN_NAME='content_schema_version' AND COLUMN_TYPE='tinyint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='1') OR (COLUMN_NAME='content_json' AND DATA_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL)))=2 THEN 1 ELSE 0 END AS complete;
ALTER TABLE question ADD COLUMN content_schema_version TINYINT UNSIGNED NOT NULL DEFAULT 1 AFTER analysis, ADD COLUMN content_json JSON NULL AFTER content_schema_version;

-- @step version_content
-- @replaces-check 015_demo_slimming/remove_version_rubric
-- @check SELECT CASE WHEN EXISTS (SELECT 1 FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version' AND TABLE_TYPE = 'BASE TABLE' AND ENGINE = 'InnoDB' AND TABLE_COLLATION = 'utf8mb4_0900_ai_ci') AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version') = 29 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version' AND ((COLUMN_NAME = 'id' AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL AND EXTRA = 'auto_increment') OR (COLUMN_NAME IN ('question_id', 'created_by') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('category_id', 'concept_id', 'regulation_id', 'regulation_version_id', 'approved_by', 'reviewed_by') AND DATA_TYPE = 'bigint' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('source_page_group', 'source_page_start', 'source_page_end') AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'revision' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'difficulty' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('type', 'source') AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'status' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(16)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'pending') OR (COLUMN_NAME = 'stem' AND DATA_TYPE = 'text' AND COLUMN_TYPE = 'text' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('options', 'answer') AND DATA_TYPE = 'json' AND COLUMN_TYPE = 'json' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'analysis' AND DATA_TYPE = 'text' AND COLUMN_TYPE = 'text' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'score_cents' AND DATA_TYPE = 'int' AND COLUMN_TYPE = 'int unsigned' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME IN ('approved_at', 'reviewed_at', 'legacy_captured_at') AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'review_reason' AND DATA_TYPE = 'varchar' AND COLUMN_TYPE = 'varchar(1000)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'created_at' AND DATA_TYPE = 'datetime' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED'))) = 27 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version') = 8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'question_version' AND ((INDEX_NAME = 'PRIMARY' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_question_version_revision' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'question_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'uk_question_version_revision' AND NON_UNIQUE = 0 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'revision' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'category_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 2 AND COLUMN_NAME = 'type' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 3 AND COLUMN_NAME = 'difficulty' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_candidate' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 4 AND COLUMN_NAME = 'status' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL) OR (INDEX_NAME = 'idx_question_version_regulation' AND NON_UNIQUE = 1 AND SEQ_IN_INDEX = 1 AND COLUMN_NAME = 'regulation_id' AND INDEX_TYPE = 'BTREE' AND SUB_PART IS NULL))) = 8 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='question_version' AND ((COLUMN_NAME='content_schema_version' AND COLUMN_TYPE='tinyint unsigned' AND IS_NULLABLE='NO' AND COLUMN_DEFAULT='1') OR (COLUMN_NAME='content_json' AND DATA_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL)))=2 THEN 1 ELSE 0 END AS complete;
ALTER TABLE question_version ADD COLUMN content_schema_version TINYINT UNSIGNED NOT NULL DEFAULT 1 AFTER analysis, ADD COLUMN content_json JSON NULL AFTER content_schema_version;

-- @step answer_ids
-- @replaces-check 015_demo_slimming/objective_answer_columns
-- @check SELECT CASE WHEN (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_answer') = 10 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'exam_answer' AND ((COLUMN_NAME = 'record_question_id' AND COLUMN_TYPE = 'bigint unsigned' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'gained_score' AND COLUMN_TYPE = 'decimal(5,2)' AND IS_NULLABLE = 'YES' AND COLUMN_DEFAULT IS NULL) OR (COLUMN_NAME = 'updated_at' AND COLUMN_TYPE = 'datetime(3)' AND IS_NULLABLE = 'NO' AND COLUMN_DEFAULT = 'CURRENT_TIMESTAMP(3)' AND EXTRA = 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP(3)'))) = 3 AND (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='exam_answer' AND COLUMN_NAME='selected_option_ids' AND DATA_TYPE='json' AND IS_NULLABLE='YES' AND COLUMN_DEFAULT IS NULL)=1 THEN 1 ELSE 0 END AS complete;
ALTER TABLE exam_answer ADD COLUMN selected_option_ids JSON NULL AFTER selected;
